using FluentValidation;namespace Namaa.Application.JournalEntries.Commands.AddJournalEntryLine;public sealed class AddJournalEntryLineCommandValidator:AbstractValidator<AddJournalEntryLineCommand>{public AddJournalEntryLineCommandValidator(){RuleFor(x=>x.JournalEntryId).GreaterThan(0);RuleFor(x=>x.AccountId).GreaterThan(0);RuleFor(x=>x).Must(x=>(x.Debit>0&&x.Credit==0)||(x.Credit>0&&x.Debit==0)).WithMessage("Supply either a positive debit or a positive credit.");RuleFor(x=>x.Description).MaximumLength(500);}}
